        const aliasesRaw = sourceNode.get("aliases", true);
        const oldAliases = isSeq(aliasesRaw) ? aliasesRaw.toJSON() : [];
        addAliasesToNode(doc, keepNode, [aliasId, ...oldAliases]);
        removeIngredientKey(ingredientsMap, aliasId);
